using Microsoft.AspNetCore.Mvc;

namespace MyFirstApp.Controllers;

public class ProductsController : Controller
{
    // GET: /Products
    public IActionResult Index()
    {
        var products = new[] { "Laptop", "Coffee Mug", "Desk Lamp" };
        return View(products); // passes the list to the view
    }

    // GET: /Products/Details/1
    public IActionResult Details(int id)
    {
        var productName = id switch
        {
            1 => "Laptop",
            2 => "Coffee Mug",
            _ => null
        };

        if (productName == null)
        {
            return NotFound(); // 404 response
        }

        return View(model: productName);
    }
}

[Route("products")]
public class ProductsController : Controller
{
    // GET /products
    [HttpGet("")]
    public IActionResult Index() => View();

    // GET /products/5
    [HttpGet("{id:int}")]
    public IActionResult Details(int id) => View(model: id);

    // GET /products/category/electronics
    [HttpGet("category/{category}")]
    public IActionResult ByCategory(string category) => View(model: category);
}

// Route: /Products/Search?term=laptop&page=1
[HttpGet("Search")]
public IActionResult Search(string term, int page = 1)
{
    // 'term' comes from the query string (?term=laptop)
    // 'page' comes from the query string (page=1) with a default value of 1
    var results = _repo.Search(term, page);
    return View(results);
}
